json-logger:logger.json-logger:content:
#[import modules::JSONLoggerModule
import * from dw::util::Timer
output application/json

var currentTimeMillis = currentMilliseconds()
---
vars.requestResponseLog ++ {
	responseStatusCode:vars.httpStatus,
	exitTimeMillis:currentTimeMillis,
	entryExitElapsed: (currentTimeMillis - (vars.requestResponseLog.entryTimeMillis default 0))
}]
